def _slates_path(slate_id: int, suffix: str) -> str:
    return f"/api/v1/dfs/slates/{slate_id}{suffix}"


def _normalize_poll_path(location: str | None, status_body: Mapping[str, Any], slate_id: int) -> str:
    raw = location or str(status_body.get("poll_url") or "")
    if not raw and status_body.get("job_id"):
        raw = _slates_path(slate_id, f"/sim/jobs/{urllib.parse.quote(str(status_body['job_id']), safe='')}")
    if not raw:
        raise StatApiError(202, {**dict(status_body), "message": "stat-api: 202 response missing Location and poll_url"}, _slates_path(slate_id, "/sim/lineups"))
    if raw.startswith("http://") or raw.startswith("https://"):
        parsed = urllib.parse.urlparse(raw)
        return parsed.path + (f"?{parsed.query}" if parsed.query else "")
    return raw


def _poll_until_ready(
    transport: HttpTransport,
    slate_id: int,
    initial_path: str,
    status: int,
    headers: Any,
    text: str,
    *,
    timeout_s: float = 120.0,
    poll_interval_s: float | None = None,
    expect_csv: bool = False,
) -> Any:
    if status != 202:
        return text if expect_csv else json.loads(text)
    deadline = time.monotonic() + timeout_s
    cur_headers = headers
    cur_text = text
    status_body = json.loads(cur_text)
    poll_path = _normalize_poll_path(cur_headers.get("Location"), status_body, slate_id)
    while True:
        if status_body.get("status") == "failed":
            raise StatApiError(500, {**dict(status_body), "message": str(status_body.get("error") or "SIM job failed")}, poll_path)
        retry_hdr = cur_headers.get("Retry-After")
        try:
            default_delay = float(retry_hdr) if retry_hdr is not None else float(status_body.get("retry_after_seconds", 1.0))
        except (TypeError, ValueError):
            default_delay = 1.0
        delay_s = poll_interval_s if poll_interval_s is not None else max(0.0, default_delay)
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise NotReadyError(202, status_body, poll_path, retry_after=retry_hdr)
        if delay_s > 0:
            time.sleep(min(delay_s, remaining))
        get_headers = {"Accept": "text/csv, application/json;q=0.9"} if expect_csv else None
        status, cur_headers, cur_text, _ = transport.request_raw("GET", poll_path, headers=get_headers, retry_5xx=True)
        if status != 202:
            return cur_text if expect_csv else json.loads(cur_text)
        status_body = json.loads(cur_text)
        poll_path = _normalize_poll_path(cur_headers.get("Location"), status_body, slate_id)


