def sim_job(
    transport: HttpTransport,
    slate_id: int,
    job_id: str,
) -> SimJobPollResult:
    path = _slates_path(slate_id, f"/sim/jobs/{urllib.parse.quote(job_id, safe='')}")
    status, headers, text, _ = transport.request_raw(
        "GET", path, headers={"Accept": "application/json, text/csv;q=0.9"}, retry_5xx=True
    )
    if status == 202:
        return {"ready": False, "status": cast(SimJobStatusResponse, json.loads(text)), "result": None, "csv": None}
    ct = str(headers.get("Content-Type") or "")
    if "text/csv" in ct:
        return {"ready": True, "status": None, "result": None, "csv": text}
    return {"ready": True, "status": None, "result": cast(SimLineupsResponse, json.loads(text)), "csv": None}


